insert into public.grammar_topics (language_code, slug, title_tr, title_target, cefr_level, summary_tr, examples, practice_items, order_index) values ('en', 'en-future-will-going-to', 'Gelecek: will ve going to', 'Future: will and going to', 'A2', '• going to → önceden verilmiş karar/plan veya şu anki kanıta dayalı tahmin: I’m going to study medicine. Look at the clouds, it’s going to rain.
insert into public.grammar_topics (language_code, slug, title_tr, title_target, cefr_level, summary_tr, examples, practice_items, order_index) values ('en', 'en-present-perfect', 'Present perfect (have / has + V3)', 'Present perfect', 'B1', 'Geçmişte başlayıp bugünle bağlantısı olan olaylar için: have/has + V3 (past participle).
insert into public.grammar_topics (language_code, slug, title_tr, title_target, cefr_level, summary_tr, examples, practice_items, order_index) values ('en', 'en-modals-obligation', 'Zorunluluk ve tavsiye (must, have to, should)', 'Modal verbs: must, have to, should', 'B1', '• must → konuşanın kendi hissettiği güçlü zorunluluk; have to → dış kurallardan gelen zorunluluk: I have to wear a uniform at work.
