insert into public.grammar_topics (language_code, slug, title_tr, title_target, cefr_level, summary_tr, examples, practice_items, order_index) values ('en', 'en-inversion', 'Devrik yapı (Never have I…, Rarely does…)', 'Inversion after negative adverbials', 'C1', 'Olumsuz veya kısıtlayıcı bir zarf cümlenin başına geldiğinde yardımcı fiil özneden önce gelir (soru düzeni gibi). Vurgu ve resmî üslup içindir.
