insert into public.grammar_topics (language_code, slug, title_tr, title_target, cefr_level, summary_tr, examples, practice_items, order_index) values ('en', 'en-cleft-sentences', 'Vurgu cümleleri (It was … who, What I need is …)', 'Cleft sentences', 'C1', 'Bir öğeyi öne çıkarmak için cümle ikiye bölünür.
